import java.io.*;import com.jpexs.decompiler.flash.SWF;import com.jpexs.decompiler.flash.abc.avm2.*;import com.jpexs.decompiler.flash.abc.avm2.instructions.*;import com.jpexs.decompiler.flash.tags.*;
/** Test copy only. Intercept socket dispatch while leaving moveToEquip byte-for-byte unchanged. */
class CosmosSlotTestInterceptor {public static void main(String[] args)throws Exception{SWF s=new SWF(new FileInputStream(args[0]),true);int count=0;for(var p:s.getAS3Packs())if(p.getClassPath().toString().equals("yishi.manager.StarManager")){var b=p.abc.findBodyByClassAndName("StarManager","starMove");AVM2Code c=new AVM2Code();c.code.add(new AVM2Instruction(0,0xd3,new int[0]));c.code.add(new AVM2Instruction(0,0x03,new int[0]));b.setCode(c);b.setModified();((Tag)p.abc.parentTag).setModified(true);count++;}if(count!=1)throw new IllegalStateException();try(var out=new FileOutputStream(args[1])){s.saveTo(out);}}}
